   SET source_body_sha256 = fix.new_sha256
  FROM fix
 WHERE d.manifestation_derivative_id = (SELECT dh.accepted_derivative_id
                                          FROM icono_manifestation_derivative_heads dh
                                         WHERE dh.manifestation_revision_id = fix.revision_id)
